use std :: path :: { Path , PathBuf } ; use std :: time :: SystemTime ; use anyhow :: { Context , Result } ; use crate :: cli :: LogsArgs ; # [doc = " Collects every regular file in `log_dir` as `(mtime, path)` pairs."] # [doc = ""] # [doc = " Uses a single `entry.metadata()` call per entry — one syscall covers both"] # [doc = " the `is_file()` check and the `modified()` timestamp."] async fn collect_files (log_dir : & Path) -> Result < Vec < (SystemTime , PathBuf) > > { let mut entries = tokio :: fs :: read_dir (log_dir) . await . with_context (| | { format ! ("Log directory not found: {}. Run forge at least once to generate logs." , log_dir . display ()) }) ? ; let mut files = Vec :: new () ; while let Some (entry) = entries . next_entry () . await ? { if let Ok (meta) = entry . metadata () . await && meta . is_file () { let mtime = meta . modified () . unwrap_or (SystemTime :: UNIX_EPOCH) ; files . push ((mtime , entry . path ())) ; } } Ok (files) }